let sourceEditIndex=null,sourceEntryInitial='';
function sourceEntry(){return {title:$('source-title').value.trim(),url:$('source-url').value.trim(),field:$('source-field').value,consultedAt:$('source-date').value,notes:$('source-notes').value.trim(),status:$('source-status').value};}
function sourceEntryDirty(){return !!$('source-title')&&JSON.stringify(sourceEntry())!==sourceEntryInitial;}
function drawSourceEditor(index=null){
 sourceEditIndex=index;const rows=playerDraft.documentSources||[],r=index===null?{title:'',url:'',field:'general',consultedAt:'',notes:'',status:'Por verificar'}:rows[index];
 $('documentSources').innerHTML=`<h3>Fontes e verificação</h3><p class="muted">Associa uma referência a um dado. A verificação do jogador é calculada a partir destas fontes. Nas observações podes identificar a transferência ou o escalão em causa.</p><p>Estado do registo: <b>${esc(Documentary.verification(playerDraft))}</b></p><div class="source-entry"><div class="player-grid"><label>Título / fonte<input id="source-title" maxlength="200" value="${esc(r.title)}"></label><label>Informação<select id="source-field">${Object.entries(Documentary.fields).map(([key,label])=>`<option value="${key}" ${r.field===key?'selected':''}>${label}</option>`).join('')}</select></label><label>URL (opcional)<input id="source-url" type="url" maxlength="2000" placeholder="https://…" value="${esc(r.url)}"></label><label>Consultada em<input id="source-date" type="date" value="${esc(r.consultedAt)}"></label><label>Estado<select id="source-status">${options(Documentary.states,r.status)}</select></label></div><label>Observações<textarea id="source-notes" maxlength="2000">${esc(r.notes)}</textarea></label><div class="toolbar"><button type="button" id="source-apply">${index===null?'Adicionar fonte':'Aplicar à fonte'}</button><button type="button" id="source-reset">${index===null?'Limpar entrada':'Cancelar edição da fonte'}</button></div><p id="source-error" role="alert"></p></div><div class="source-list">${rows.length?rows.map((x,i)=>`<article class="source-row"><div><b>${esc(x.title)}</b><p>${esc(Documentary.fields[x.field]||x.field)} · ${esc(x.status)}${x.consultedAt?' · '+esc(x.consultedAt):''}</p>${Documentary.safeUrl(x.url)?`<a href="${esc(Documentary.safeUrl(x.url))}" target="_blank" rel="noopener noreferrer">Abrir fonte</a>`:''}${x.notes?`<p class="record-notes">${esc(x.notes)}</p>`:''}</div><div><button type="button" data-source-edit="${i}">Editar</button><button type="button" data-source-remove="${i}">Remover</button></div></article>`).join(''):'<p class="muted">Sem fontes registadas.</p>'}</div>`;
 sourceEntryInitial=JSON.stringify(sourceEntry());
 $('source-apply').onclick=()=>commitSourceEntry();$('source-reset').onclick=()=>drawSourceEditor();
 const canSwitch=()=>{if(sourceEntryDirty()){$('source-error').textContent='Aplica ou cancela a entrada em edição antes de escolher outra fonte.';return false;}return true;};
 $('documentSources').querySelectorAll('[data-source-edit]').forEach(b=>b.onclick=()=>{if(canSwitch())drawSourceEditor(+b.dataset.sourceEdit);});
 $('documentSources').querySelectorAll('[data-source-remove]').forEach(b=>b.onclick=()=>{if(!canSwitch())return;playerDraft.documentSources.splice(+b.dataset.sourceRemove,1);drawSourceEditor();drawPlayer();});
}
function commitSourceEntry(){
 try{
  const root=$('documentSources');for(const input of root.querySelectorAll('.source-entry input,.source-entry textarea'))if(!input.reportValidity())return false;
  const rows=(playerDraft.documentSources||[]).map(r=>({...r})),entry=sourceEntry();if(sourceEditIndex===null)rows.push(entry);else rows[sourceEditIndex]=entry;
  Documentary.validatePlayer({documentaryVersion:1,documentSources:rows});playerDraft.documentSources=rows;playerDraft.documentaryVersion=1;drawSourceEditor();drawPlayer();return true;
 }catch(e){$('source-error').textContent=e.message;return false;}
}
function drawDocumentCompleteness(){
 const root=$('documentCompleteness');if(!root)return;const opened=root.querySelector('details')?.open,c=Documentary.completeness(playerDraft,s);
 root.innerHTML=`<details ${opened?'open':''}><summary><b>Dados ${c.percent}% completos</b> <span class="muted">${c.done}/${c.total} critérios documentais</span></summary><progress value="${c.percent}" max="100" aria-label="Completude documental">${c.percent}%</progress><ul class="completeness-list">${c.checks.map(x=>`<li class="${!x.applicable?'not-applicable':x.ok?'complete':'incomplete'}">${!x.applicable?'—':x.ok?'✓':'○'} ${esc(x.label)}${!x.applicable?' · Não aplicável':x.ok?'':' · Por completar'}</li>`).join('')}</ul><p class="muted">Mede presença, não veracidade. AVG, skills e estatísticas do motor não contam. O histórico estatístico real conta como critério documental.</p></details>`;
}
